from pathlib import Path
import base64, sys, zlib

root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
payloads = {
    'src/main/java/com/loyacrown/enderlegacy/blockentity/FarmingStationBlockEntity.java': '',
    'src/main/java/com/loyacrown/enderlegacy/menu/FarmingStationMenu.java': '',
    'src/main/java/com/loyacrown/enderlegacy/client/FarmingStationScreen.java': '',
    'src/main/java/com/loyacrown/enderlegacy/client/DimensionalTransceiverScreen.java': '',
    'src/main/java/com/loyacrown/enderlegacy/client/InventoryPanelScreen.java': '',
    'PARITY_RULES.md': '',
}

props = root / "gradle.properties"
text = props.read_text()
if "mod_version=0.6.0-alpha" not in text:
    raise RuntimeError("Expected validated 0.6.0-alpha source as the patch base")
props.write_text(text.replace("mod_version=0.6.0-alpha", "mod_version=0.6.1-alpha", 1))

for relative, encoded in payloads.items():
    target = root / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(zlib.decompress(base64.b64decode(encoded)))

changelog = root / "CHANGELOG.md"
if changelog.exists():
    old = changelog.read_text()
    heading = "## 0.6.1-alpha - SkyFactory 3 behavior / modern Ender IO UI pass\n\n- Replaced the Farming Station's permanent gray side panel with a compact current-Ender-IO-style control stack and I/O overlay.\n- Restored four independent Farming Station supply-slot locks from the legacy machine behavior.\n- Added a working Farming Station range visibility toggle with a world range preview.\n- Kept per-side item I/O and redstone modes while presenting them through the compact machine UI.\n- Restyled the Dimensional Transceiver and Inventory Panel screens into the same dark machine family without changing their legacy textures.\n- Added explicit parity rules: SkyFactory 3-era behavior first; newest working Ender IO implementation when legacy behavior is incomplete; Forge 1.20.1 remains the target.\n\n"
    if "## 0.6.1-alpha" not in old:
        changelog.write_text(heading + old)

print(f"Applied 0.6.1 parity/UI patch to {root}")
